# Source: src/common/legacy_ldbll/regression/misc.py
import math


import torch


import torch.nn as nn


_INPUT_NORMALIZATION_MODE = "whiten"


def set_input_normalization_mode(mode):
    global _INPUT_NORMALIZATION_MODE
    if mode not in {"whiten", "standard"}:
        raise ValueError(f"Unsupported input normalization mode: {mode}")
    _INPUT_NORMALIZATION_MODE = mode


def get_input_normalization_mode():
    return _INPUT_NORMALIZATION_MODE


def z_score_params(X, eps=1e-5):
    """
    Implements z-score data normalization.

    Parameters:
        X (torch.Tensor)[*, k]: The un-normalized data.

    Keywords:
        eps (float): Small value for numerical stability.

    Returns:
        mu (torch.Tensor)[k]: The mean vector.
        sigma (torch.Tensor)[k]: The standard deviations.
    """
    sigma, mu = torch.std_mean(X, dim=0)
    return mu, sigma + eps


def whitening_params(X, eps=1e-5):
    """
    Implements ZCA data whitening.

    Parameters:
        X (torch.Tensor)[*, k]: The un-whitened data.

    Keywords:
        eps (float): Small value for numerical stability.

    Returns:
        ZCA_mean (torch.Tensor)[k]: The ZCA whitening mean.
        ZCA_cov (torch.Tensor)[k, k]: The ZCA whitening covariance.
    """
    X_mean = torch.mean(X, dim=0)
    X_centered = X - X_mean

    if _INPUT_NORMALIZATION_MODE == "standard":
        std = torch.sqrt(torch.mean(X_centered ** 2, dim=0)).clamp_min(eps)
        return X_mean, torch.diag(1.0 / std)

    Sigma = X_centered.t() @ X_centered / X.shape[0]
    U, S, _ = torch.svd(Sigma)
    ZCA_mean = X_mean
    ZCA_cov = U @ torch.diag(torch.sqrt(S + eps) ** -1) @ U.t()
    return ZCA_mean, ZCA_cov


def whiten(x, mu, Sigma):
    """
    Applies ZCA whitening using previously computed mu and Sigma.

    Parameters:
        x (torch.Tensor)[n, k]: The un-whitened data.
        mu (torch.Tensor)[k]: The previously computed ZCA whitening mean vector.
        Sigma (torch.Tensor)[k, k]: The previously computed ZCA whitening covariance matrix.

    Returns:
        x' (torch.Tensor)[n, k]: The whitened data.
    """
    if x is None:
        return None

    if mu is None or Sigma is None:
        return x

    device = x.device
    if mu.device != device:
        mu = mu.to(device)
    if Sigma.device != device:
        Sigma = Sigma.to(device)

    return (x - mu) @ Sigma


def z_score(X, mu, sigma):
    """
    Safe z-score normalization with device consistency.

    Parameters:
        X (torch.Tensor)[n, k]
        mu (torch.Tensor)[k] or None
        sigma (torch.Tensor)[k] or None

    Returns:
        (X - mu) / sigma, on the same device as X
        or X itself if mu/sigma are None
    """

    if X is None:
        return None

    # If z-scoring disabled → pass-through
    if mu is None or sigma is None:
        return X

    device = X.device

    # Move to same device as X
    if mu.device != device:
        mu = mu.to(device)
    if sigma.device != device:
        sigma = sigma.to(device)

    return (X - mu) / sigma


def inverse_z_score(X, sigma, mu=None):
    """
    Reverses z_score normalization using previously computed mu and sigma.
    """

    device = X.device

    # Move sigma and mu to same device as X (GPU/CPU safe)
    if sigma is not None and sigma.device != device:
        sigma = sigma.to(device)
    if mu is not None and mu.device != device:
        mu = mu.to(device)

    if mu is None:
        return (sigma ** 2).diag().repeat(X.shape[0], 1, 1).bmm(X)
    else:
        return sigma * X + mu


def mvn_logprob(mean, Variance, x):
    """
    Computes multivariate normal distribution logprob of a value.

    Parameters:
        mean (torch.Tensor)[n, *]: The mean vectors of the multivariate normal distribution.
        Variance (torch.Tensor)[n, *, *]: The covariance matrices of the multivariate normal distribution.
        x (torch.Tensor)[n, *]: The vectors whose logprob shall be computed.

    Returns:
        logprob (torch.Tensor)[n]: The logprob values.
    """
    p = x.shape[-1]
    assert mean.shape[-1] == p and Variance.shape[-1] == p and Variance.shape[-2] == p
    c = -.5 * Variance.logdet()
    c += -.5 * p * math.log(2 * math.pi)
    diff = (x - mean).unsqueeze(-1)
    logprob = -.5 * diff.transpose(-2, -1).bmm(Variance.inverse()).bmm(diff)
    return c + logprob.squeeze()


def mvn_entropy(Variance):
    """
    Computes multivariate normal distribution entropy.

    Parameters:
        Variance (torch.Tensor)[n, *, *]: The covariance matrices of the multivariate normal distribution.

    Returns:
        entropy (torch.Tensor)[n]: The entropy values.
    """
    p = Variance.shape[-1]
    assert Variance.shape[-2] == p
    c = .5 * p * (math.log(2 * math.pi) + 1)
    return c + .5 * Variance.logdet()


def mvt_logprob(nu, loc, Scale, x):
    """
    Computes multivariate Student-t distribution logprob of a value.

    Parameters:
        nu (torch.Tensor)[1]: The degree of freedom parameter of the distributions.
        loc (torch.Tensor)[n, *]: The location vectors of the multivariate Student-t distribution.
        Scale (torch.Tensor)[n, *, *]: The scale matrices of the multivariate Student-t distribution.
        x (torch.Tensor)[n, *]: The vectors whose logprob shall be computed.

    Returns:
        logprob (torch.Tensor)[n]: The logprob values.
    """
    p = x.shape[-1]
    assert nu.item() > 0
    assert loc.shape[-1] == p and Scale.shape[-1] == p and Scale.shape[-2] == p
    c = -.5 * Scale.logdet()
    c += torch.lgamma(.5 * (nu + p)) - torch.lgamma(.5 * nu)
    c += -.5 * p * (torch.log(nu) + math.log(math.pi))
    diff = (x - loc).unsqueeze(-1)
    logprob = -.5 * (nu + p) * torch.log(1 + (nu ** -1) * diff.transpose(-2, -1).bmm(Scale.inverse()).bmm(diff))
    return c + logprob.squeeze()


def mvt_entropy(nu, Scale):
    """
    Computes multivariate Student-t distribution entropy.

    Parameters:
        nu (torch.Tensor)[1]: The degree of freedom parameter of the distributions.
        Scale (torch.Tensor)[n, *, *]: The scale matrices of the multivariate Student-t distribution.

    Returns:
        entropy (torch.Tensor)[n]: The entropy values.
    """
    p = Scale.shape[-1]
    assert nu.item() > 0
    assert Scale.shape[-2] == p
    c = torch.lgamma(.5 * nu) - torch.lgamma(.5 * (nu + p))
    c += .5 * p * (torch.log(nu) + math.log(math.pi))
    c += .5 * (nu + p) * (torch.digamma(.5 * (nu + p)) - torch.digamma(.5 * nu))
    return c + .5 * Scale.logdet()


def get_activation(activation):
    """
    Translates name of an activation function into the corresponding PyTorch implementation.

    Parameters:
        activation (str): Name of the desired activation function.

    Returns:
        {0} (torch.nn.Module): PyTorch implementation of the activation function.
    """
    activation_dict = {
        'sigmoid': nn.Sigmoid,
        'relu': nn.ReLU,
        'softplus': nn.Softplus,
        'tanh': nn.Tanh,
        'leaky_relu': nn.LeakyReLU
    }
    try:
        return activation_dict[activation]
    except KeyError:
        print("Specified activation function is not implemented. "
              "Please choose one of the following: "
              "'sigmoid', 'relu', 'softplus', 'tanh', 'leaky_relu'")
        exit(1)



# Source: src/common/legacy_ldbll/regression/base.py
import torch


class RegressionModel:
    """
    This class serves as an abstract RegressionModel template
    that handles data preparation, such as whitening, and
    keeps track of optimization traces.

    Attributes:
        k (int): The number of input dimensions of the regression model.
        d (int): The number of output dimensions of the regression model.
        device (torch.device): The current computing device.
        input_ZCA_mean (torch.Tensor)[k]: Mean of the input data (for ZCA whitening).
        input_ZCA_matrix (torch.Tensor)[k, k]: Variances of the input data (for ZCA whitening).
        output_mean (float): Mean of the output data (for ZCA whitening).
        output_std (float): Standard deviation of the output data (for ZCA whitening).
        traces (dict): Dictionary to store optimization traces.
    """

    def __init__(self, input_dim, output_dim, device=torch.device('cpu')):
        """
        The constructor for RegressionModel.

        Parameters:
            input_dim (int): The number of input dimensions of the regression model.
            output_dim (int): The number of output dimensions of the regression model.

        Keywords:
            device (torch.device): The current computing device.
        """
        self.k = input_dim
        self.d = output_dim
        self.device = device
        # initialize whitening to identity
        self.input_mean = torch.zeros(input_dim)
        self.input_cov = torch.eye(input_dim)
        self.output_mean = torch.zeros(output_dim)
        self.output_std = torch.ones(output_dim)
        # optimization trace
        self.traces = {}
        self._reset_traces()

    def _reset_traces(self):
        """
        Resets optimization traces.
        """
        self.traces['objective'] = []
        self.traces['val_rmse'] = []
        self.traces['val_llh'] = []
        self.traces['val_pred_entropy'] = []
        self.traces['test_rmse'] = []
        self.traces['test_llh'] = []
        self.traces['test_pred_entropy'] = []
        self.traces['kld'] = []

    def _prepare_data(self, X_train, Y_train, X_val, Y_val, X_test, Y_test, whiten_input=True, z_score_output=True):
        """
        Checks data dimensions, stores data and computes whitening parameters.

        Parameters:
            X_train (torch.Tensor)[n, k]: The input training data.
            Y_train (torch.Tensor)[n]: The output training data.
            X_val (torch.Tensor)[n_val, k]: Optional input validation data.
            Y_val (torch.Tensor)[n_val]: Optional output validation data.
            X_test (torch.Tensor)[n_test, k]: Optional input test data (for visualization only).
            Y_test (torch.Tensor)[n_test]: Optional output test data (for visualization only).
        """
        assert isinstance(X_train, torch.Tensor)
        assert isinstance(Y_train, torch.Tensor)
        assert X_train.shape[0] == Y_train.shape[0]
        assert X_train.shape[1] == self.k
        assert Y_train.shape[1] == self.d
        self.n = X_train.shape[0]
        self.X_train = X_train.to(self.device)
        self.Y_train = Y_train.to(self.device)
        if X_val is not None:
            assert isinstance(X_val, torch.Tensor)
            assert isinstance(Y_val, torch.Tensor)
            assert X_val.shape[0] == Y_val.shape[0]
            assert X_val.shape[1] == self.k
            assert Y_val.shape[1] == self.d
            self.X_val = X_val.to(self.device)
            self.Y_val = Y_val.to(self.device)
        else:
            self.X_val = None
            self.Y_val = None
        if X_test is not None:
            assert isinstance(X_test, torch.Tensor)
            assert isinstance(Y_test, torch.Tensor)
            assert X_test.shape[0] == Y_test.shape[0]
            assert X_test.shape[1] == self.k
            assert Y_test.shape[1] == self.d
            self.X_test = X_test.to(self.device)
            self.Y_test = Y_test.to(self.device)
        else:
            self.X_test = None
            self.Y_test = None
        if whiten_input:
            self.input_mean, self.input_cov = whitening_params(self.X_train)
        if z_score_output:
                self.output_mean, self.output_std = z_score_params(self.Y_train)
        # input ZCA whitening
        self.X_train_whitened = whiten(self.X_train, self.input_mean, self.input_cov)
        self.X_val_whitened = whiten(self.X_val, self.input_mean, self.input_cov) if self.X_val is not None else None
        self.X_test_whitened = whiten(self.X_test, self.input_mean, self.input_cov) if self.X_test is not None else None
        # output z-score whitening
        self.Y_train_whitened = z_score(self.Y_train, self.output_mean, self.output_std)

    def _running_eval(self):
        """
        Computes and stores validation and/or test evaluation metrics if specified.
        """
        # add validation RMSE and LLH to trace
        if self.X_val is not None:
            val_rmse, val_llh, val_pred_entropy = self.evaluate(self.X_val_whitened, self.Y_val, whiten_input=False, requires_grad=False)
            self.traces['val_rmse'].append(val_rmse)
            self.traces['val_llh'].append(val_llh)
            self.traces['val_pred_entropy'].append(val_pred_entropy)
        # add test RMSE and LLH to trace
        if self.X_test is not None:
            test_rmse, test_llh, test_pred_entropy = self.evaluate(self.X_test_whitened, self.Y_test, whiten_input=False, requires_grad=False)
            self.traces['test_rmse'].append(test_rmse)
            self.traces['test_llh'].append(test_llh)
            self.traces['test_pred_entropy'].append(test_pred_entropy)

    def fit(self, *args, **kwargs):
        """
        Fits the model to the training data. To be implemented by inheriting classes.
        """
        raise NotImplementedError

    def _predict(self, X_, requires_grad=False):
        raise NotImplementedError

    def predict_mean_aleatoric_epistemic(self, X_, whiten_input=True, requires_grad=False):
        """
        Computes mean, aleatoric uncertainty and epistemic uncertainty.

        Parameters:
            X_ (torch.Tensor)[*, k]: The new input data.

        Keywords:
            whiten_input (bool): Whether the new input data should be whitened.
            requires_grad (bool): Whether gradients are required or not.

        Returns:
            mean (torch.Tensor)[*, d]: The predictive mean.
            aleatoric (torch.Tensor)[*, d]: The aleatoric uncertainty.
            epistemic (torch.Tensor)[*, d]: The epistemic uncertainty.
        """
        X_ = X_.to(self.device)
        if whiten_input:
            X_ = whiten(X_, self.input_mean, self.input_cov)
        mean, aleatoric, epistemic = self._predict(X_, requires_grad=requires_grad)
        # unwhiten prediction
        mean = inverse_z_score(mean, self.output_std, self.output_mean)
        aleatoric = inverse_z_score(aleatoric, self.output_std)
        epistemic = inverse_z_score(epistemic, self.output_std)
        return mean, aleatoric, epistemic

    def predict_mean_variance(self, X_, whiten_input=True, requires_grad=False):
        """
        Computes mean variance using the posterior predictive.

        Parameters:
            X_ (torch.Tensor)[*, k]: The new input data.

        Keywords:
            whiten_input (bool): Whether the new input data should be whitened.
            requires_grad (bool): Whether gradients are required or not.

        Returns:
            mean (torch.Tensor)[*]: The predictive mean.
            variance (torch.Tensor)[*]: The variance, i.e. sum of aleatoric and epistemic uncertainty.
        """
        mean, aleatoric, epistemic = self.predict_mean_aleatoric_epistemic(X_,
                                                                           whiten_input=whiten_input,
                                                                           requires_grad=requires_grad)
        return mean, aleatoric + epistemic

    def predict(self, X_, whiten_input=True, requires_grad=False):
        """
        Alias for 'self.predict_mean_variance'.
        """
        return self.predict_mean_variance(X_, whiten_input=whiten_input, requires_grad=requires_grad)

    def evaluate(self, X_, Y_, whiten_input=True, requires_grad=False):
        """
        Computes RMSE, log-likelihood and predictive entropy for a batch of data.
        To be implemented by inheriting classes.

        Parameters:
            X_ (torch.Tensor)[*, k]: The input data.
            Y_ (torch.Tensor)[*]: The ground truth output data.

        Keywords:
            whiten_input (bool): Whether the new input data should be whitened.
            requires_grad (bool): Whether gradients are required or not.

        Returns:
            RMSE (float): The root mean squared error between prediction and ground truth.
            LLH (float): The average log-likelihood of the ground truth output w.r.t. the prediction.
            ENTR (float): The average entropy of the predictive distribution.
        """
        mean, variance = self.predict_mean_variance(X_,
                                                    whiten_input=whiten_input,
                                                    requires_grad=requires_grad)
        with torch.set_grad_enabled(requires_grad):
            rmse = ((mean - Y_) ** 2).sum(dim=1).mean().sqrt()
            llh = mvn_logprob(mean, variance, Y_).mean()
            entr = mvn_entropy(variance).mean()
        return rmse.item(), llh.item(), entr.item()

    def _add_whitening_params(self, state_dict):
        """
        Adds previously computed whitening parameters to a dictionary for model saving.

        Parameters:
            state_dict (dict): The dictionary to be saved to the disk.
        """
        state_dict['input_mean'] = self.input_mean
        state_dict['input_cov'] = self.input_cov
        state_dict['output_mean'] = self.output_mean
        state_dict['output_std'] = self.output_std

    def save(self, filepath):
        """
        Saves the current model to the disk, only keeping prediction variables, no optimization information.
        To be implemented by inheriting classes.

        Parameters:
            filepath (str): The destination to save the model.
        """
        raise NotImplementedError

    def _pop_whitening_params(self, state_dict):
        """
        Retrieves previously computed whitening parameters from a saved model.

        Parameters:
            state_dict (dict): The previously saved model's dictionary.
        """
        self.input_mean = state_dict.pop('input_mean')
        self.input_cov = state_dict.pop('input_cov')
        self.output_mean = state_dict.pop('output_mean')
        self.output_std = state_dict.pop('output_std')

    def load(self, filepath):
        """
        Loads a previously saved model from the disk. To be implemented by inheriting classes.

        Parameters:
            filepath (str): The destination of the saved model.
        """
        raise NotImplementedError

    def to(self, device):
        """
        Transfers this model to another device (CPU or GPU).

        Parameters:
            device (torch.device): The destination device.
        """
        self.device = device
        for k, v in vars(self).items():
            if hasattr(v, 'to'):
                vars(self)[k] = vars(self)[k].to(device)



# Source: src/common/legacy_ldbll/regression/dual_layers.py
import torch


import torch.nn as nn


import torch.nn.functional as functional


class DualModule(nn.Module):
    """
    Based on torch.nn.Module, this class implements a neural network module
    that can jointly compute a function and its Jacobian w.r.t. the input.
    It represents 'phi' for the Bayesian last layer.

    Attributes:
        device (torch.device): The current computing device.
        k (int): The number of input dimensions of the first layer.
        linear (bool): Whether to append linear / identity features or not.
        bias (bool): Whether to append bias / constant term or not.
    """

    def __init__(self, input_dim, hidden_dims, activation, hidden_bias=True, linear=True, bias=True):
        """
        The constructor for DualModule.

        Parameters:
            input_dim (int): The number of input dimensions of the first layer.
            hidden_dims (list[int] or tuple[int]): List of neural network layer dimensions.
            activation (str): The name of a nonlinear activation function.

        Keywords:
            hidden_bias (bool): Whether to use bias / constant terms for neural network layers.
            linear (bool): Whether to append linear / identity features.
            bias (bool): Whether to append bias / constant term or not.
            device (str): The name of the current computing device.
        """
        super().__init__()
        self.k = input_dim
        self.linear = linear
        self.bias = bias
        dims = [input_dim] + list(hidden_dims)
        layers = []
        for j in range(len(dims) - 1):
            layers.append(DualLinear(dims[j], dims[j + 1], bias=hidden_bias))
            layers.append(DualActivation(activation)())
        for idx, module in enumerate(layers):
            self.add_module(str(idx), module)
        self.m = dims[-1]

    def forward(self, X, requires_grad=True):
        """
        Computes a forward pass through this DualModule, appending linear features and bias if specified.

        Parameters:
            X (torch.Tensor)[n, k]: The input data matrix (or vector).

        Keywords:
            requires_grad (bool): Whether gradients are required or not.

        Returns:
            function (torch.Tensor)[n, m]: The function output including linear features and bias if specified.
            jacobian (torch.Tensor)[n, m, k]: The Jacobians of the function w.r.t. to the input.
        """
        # expects whitened input!
        n = X.shape[0]
        with torch.set_grad_enabled(requires_grad):
            function = X
            jacobian = torch.eye(self.k, device=function.device).reshape(1, self.k, self.k).repeat(n, 1, 1)
            for module in self._modules.values():
                function, jacobian = module((function, jacobian))
        # add linear features
        if self.linear:
            function = torch.cat((function, X), dim=1)
            jacobian = torch.cat((jacobian, torch.eye(self.k, device=jacobian.device).repeat(n, 1, 1)), dim=1)
        # add bias term
        if self.bias:
            function = torch.cat((function, torch.ones(n, 1, device=function.device)), dim=1)
            jacobian = torch.cat((jacobian, torch.zeros(n, 1, self.k, device=jacobian.device)), dim=1)
        return function, jacobian

    def function(self, X, requires_grad=True):
        """
        Computes a forward pass through this DualModule without computing Jacobians.

        Parameters:
            X (torch.Tensor)[n, k]: The input data matrix (or vector).

        Keywords:
            requires_grad (bool): Whether gradients are required or not.

        Returns:
            function (torch.Tensor)[n, m]: The function output including linear features and bias if specified.
        """
        n = X.shape[0]
        with torch.set_grad_enabled(requires_grad):
            function = X
            for module in self._modules.values():
                function = module.function(function)
        # add linear features
        if self.linear:
            function = torch.cat((function, X), dim=1)
        # add bias term
        if self.bias:
            function = torch.cat((function, torch.ones(n, 1, device=function.device)), dim=1)
        return function

    def jacobian(self, X, requires_grad=True):
        """
        Computes a forward pass through this DualModule only returning the Jacobians.

        Parameters:
            X (torch.Tensor)[n, k]: The input data matrix (or vector).

        Keywords:
            requires_grad (bool): Whether gradients are required or not.

        Returns:
            jacobian (torch.Tensor)[n, m, k]: The Jacobians of the function w.r.t. to the input.
        """
        _, jacobian = self.forward(X, requires_grad=requires_grad)
        return jacobian


class DualIdentity(nn.Module):
    """
    This class implements an identity operation.
    """
    def forward(self, x):
        return x


class DualPolynomial(nn.Module):
    """
    This class implements polynomial regression features.

    Attributes:
        device (torch.device): The current computing device.
        m (int): The maximal degree of the polynomial features.
    """

    def __init__(self, degree):
        """
        Constructor for Polynomial.

        Parameters:
            degree (int): The maximal degree of the polynomial features.

        Keywords:
            device (torch.device): The current computing device.
        """
        super().__init__()
        self.m = degree

    def forward(self, x, requires_grad=False):
        """
        Computes polynomial features and their Jacobian w.r.t. the input.

        Parameters:
            x (torch.Tensor)[n, 1]: The input data.

        Keywords:
            requires_grad (bool): Whether gradients are required or not.

        Returns:
            function (torch.Tensor)[n, m]: The polynomial features.
            jacobian (torch.Tensor)[n, m, 1]: The corresponding Jacobians w.r.t. the input.
        """
        return self.function(x, requires_grad=requires_grad), self.jacobian(x, requires_grad=requires_grad)

    def function(self, x, requires_grad=False):
        """
        Computes polynomial features without computing Jacobians.

        Parameters:
            x (torch.Tensor)[n, 1]: The input data.

        Keywords:
            requires_grad (bool): Whether gradients are required or not.

        Returns:
            function (torch.Tensor)[n, m]: The polynomial features.
        """
        n, k = x.shape
        function = torch.zeros(x.shape[0], self.m)
        for i in range(self.m):
            function[:, i] = (x ** (i + 1)).flatten()
        function = torch.cat((function, torch.ones(n, 1, device=function.device)), dim=1)
        return function

    def jacobian(self, x, requires_grad=False):
        """
        Computes polynomial features, only returning the Jacobians.

        Parameters:
            x (torch.Tensor)[n, 1]: The input data.

        Keywords:
            requires_grad (bool): Whether gradients are required or not.

        Returns:
            jacobian (torch.Tensor)[n, m, 1]: The Jacobians of the polynomial features w.r.t. to the input.
        """
        n, k = x.shape
        jacobian = torch.zeros(x.shape[0], self.m, 1, device=x.device)
        for i in range(self.m):
            jacobian[:, i, 0] = ((i + 1) * x ** i).flatten()
        jacobian = torch.cat((jacobian, torch.zeros(n, 1, k, device=jacobian.device)), dim=1)
        return jacobian


class DualLinear(nn.Linear):
    """
    Based on torch.nn.Linear, this class implements a linear layer
    that can jointly compute a function and its Jacobian w.r.t. the input.

    Attributes:
        in_features (int): The number of input features of this layer.
        out_features (int): The number of output features of this layer.
        bias (bool): Whether to use bias / constant term for this layers.
    """

    def __init__(self, in_features, out_features, bias=True):
        super().__init__(in_features, out_features, bias=bias)

    def forward(self, input):
        """
        Computes a forward pass through this linear layer.

        Parameters:
            input (torch.Tensor)[n, in_features]: The input data matrix (or vector) for this layer.

        Returns:
            {0} (torch.Tensor)[n, out_features]: The linear layer output.
            {1} (torch.Tensor)[n, out_features, k]: The Jacobians w.r.t. to the initial input.
        """
        x, dx = input
        return functional.linear(x, self.weight, self.bias), self.weight @ dx

    def function(self, x):
        """
        Computes a forward pass through this linear layer, only returning the function value.

        Parameters:
            input (torch.Tensor)[n, in_features]: The input data matrix (or vector) for this layer.

        Returns:
            {0} (torch.Tensor)[n, out_features]: The linear layer output.
        """
        return functional.linear(x, self.weight, self.bias)


class DualSigmoid(nn.Module):
    """
    Based on torch.nn.Module, this class implements a Sigmoid activation
    that can jointly compute a function and its Jacobian w.r.t. the input.
    """

    def forward(self, input):
        """
        Computes a forward pass through this nonlinear activation function.

        Parameters:
            input (torch.Tensor)[n, *]: The input data matrix (or vector) for this layer.

        Returns:
            {0} (torch.Tensor)[n, *]: The nonlinear activation output.
            {1} (torch.Tensor)[n, *, k]: The Jacobians w.r.t. to the initial input.
        """
        x, dx = input
        out = torch.sigmoid(x)
        dout = out * (torch.ones_like(out) - out)
        return out, dout.unsqueeze(-1) * dx

    def function(self, x):
        """
        Computes a forward pass through this nonlinear activation function.

        Parameters:
            input (torch.Tensor)[n, *]: The input data matrix (or vector) for this layer.

        Returns:
            {0} (torch.Tensor)[n, *]: The nonlinear activation output.
        """
        return torch.sigmoid(x)


class DualReLU(nn.Module):
    """
    Based on torch.nn.Module, this class implements a ReLU activation
    that can jointly compute a function and its Jacobian w.r.t. the input.
    """

    def forward(self, input):
        """
        Computes a forward pass through this nonlinear activation function.

        Parameters:
            input (torch.Tensor)[n, *]: The input data matrix (or vector) for this layer.

        Returns:
            {0} (torch.Tensor)[n, *]: The nonlinear activation output.
            {1} (torch.Tensor)[n, *, k]: The Jacobians w.r.t. to the initial input.
        """
        x, dx = input
        out = torch.relu(x)
        dout = out > 0.
        return out, dout.float().unsqueeze(-1) * dx

    def function(self, x):
        """
        Computes a forward pass through this nonlinear activation function.

        Parameters:
            input (torch.Tensor)[n, *]: The input data matrix (or vector) for this layer.

        Returns:
            {0} (torch.Tensor)[n, *]: The nonlinear activation output.
        """
        return torch.relu(x)


class DualSoftplus(nn.Module):
    """
    Based on torch.nn.Module, this class implements a Softplus activation
    that can jointly compute a function and its Jacobian w.r.t. the input.
    """

    def __init__(self, beta=1, threshold=20):
        """
        Refer to PyTorch's documentation for these parameters.
        """
        super().__init__()
        self.beta = beta
        self.threshold = threshold

    def forward(self, input):
        """
        Computes a forward pass through this nonlinear activation function.

        Parameters:
            input (torch.Tensor)[n, *]: The input data matrix (or vector) for this layer.

        Returns:
            {0} (torch.Tensor)[n, *]: The nonlinear activation output.
            {1} (torch.Tensor)[n, *, k]: The Jacobians w.r.t. to the initial input.
        """
        x, dx = input
        out = functional.softplus(x, beta=self.beta, threshold=self.threshold)
        dout = torch.sigmoid(self.beta * x)
        return out, dout.unsqueeze(-1) * dx

    def function(self, x):
        """
        Computes a forward pass through this nonlinear activation function.

        Parameters:
            input (torch.Tensor)[n, *]: The input data matrix (or vector) for this layer.

        Returns:
            {0} (torch.Tensor)[n, *]: The nonlinear activation output.
        """
        return functional.softplus(x)


class DualTanh(nn.Module):
    """
    Based on torch.nn.Module, this class implements a Tanh activation
    that can jointly compute a function and its Jacobian w.r.t. the input.
    """

    def forward(self, input):
        """
        Computes a forward pass through this nonlinear activation function.

        Parameters:
            input (torch.Tensor)[n, *]: The input data matrix (or vector) for this layer.

        Returns:
            {0} (torch.Tensor)[n, *]: The nonlinear activation output.
            {1} (torch.Tensor)[n, *, k]: The Jacobians w.r.t. to the initial input.
        """
        x, dx = input
        out = torch.tanh(x)
        dout = torch.ones_like(out) - (out ** 2)
        return out, dout.unsqueeze(-1) * dx

    def function(self, x):
        """
        Computes a forward pass through this nonlinear activation function.

        Parameters:
            input (torch.Tensor)[n, *]: The input data matrix (or vector) for this layer.

        Returns:
            {0} (torch.Tensor)[n, *]: The nonlinear activation output.
        """
        return torch.tanh(x)


class DualLeakyReLU(nn.Module):
    """
    Based on torch.nn.Module, this class implements a LeakyReLU activation
    that can jointly compute a function and its Jacobian w.r.t. the input.
    """
    def __init__(self, negative_slope=0.01):
        """
        Refer to PyTorch's documention for this parameter.
        """
        super().__init__()
        self.negative_slope = negative_slope

    def forward(self, input):
        """
        Computes a forward pass through this nonlinear activation function.

        Parameters:
            input (torch.Tensor)[n, *]: The input data matrix (or vector) for this layer.

        Returns:
            {0} (torch.Tensor)[n, *]: The nonlinear activation output.
            {1} (torch.Tensor)[n, *, k]: The Jacobians w.r.t. to the initial input.
        """
        x, dx = input
        out = functional.leaky_relu(x, negative_slope=self.negative_slope)
        dout = torch.ones_like(x)
        dout[out < 0] = self.negative_slope
        return out, dout.unsqueeze(-1) * dx

    def function(self, x):
        """
        Computes a forward pass through this nonlinear activation function.

        Parameters:
            input (torch.Tensor)[n, *]: The input data matrix (or vector) for this layer.

        Returns:
            {0} (torch.Tensor)[n, *]: The nonlinear activation output.
        """
        return functional.leaky_relu(x, negative_slope=self.negative_slope)


def DualActivation(activation):
    """
    Translates name of an activation function into the corresponding DualModule implementation.

    Parameters:
        activation (str): Name of the desired activation function.

    Returns:
        {0} (DualModule): DualModule implementation of the activation function.
    """
    activation_dict = {
        'sigmoid': DualSigmoid,
        'relu': DualReLU,
        'softplus': DualSoftplus,
        'tanh': DualTanh,
        'leaky_relu': DualLeakyReLU
    }
    try:
        return activation_dict[activation]
    except KeyError:
        print("Specified activation function is not implemented. "
              "Please choose one of the following: "
              "'sigmoid', 'relu', 'softplus', 'tanh', 'leaky_relu'")
        exit(1)



