class BayesianLastLayer(RegressionModel):
    """
        Based on RegressionModel, this class implements a Bayesian last layer network.

        Attributes:
            m (int): The number of features without linear and bias terms.
            m_ (int): The number of features including linear and bias terms.
            optimize_prior (bool): Whether to use empirical Bayes or not.
            Lam_0_raw (torch.Tensor)[m_]: Proxy for Lam_0 to assert positive constraint.
            params (list[torch.Tensor]): Parameters to be optimized during training.
            Mu_n (torch.Tensor)[m_, d]: Posterior weight mean matrix.
            Lam_n (torch.Tensor)[m_, m_]: Posterior weight row precision matrix.
            Lam_n_inv (torch.Tensor)[m_, m_]: Posterior weight row variance matrix.
        """

    def __init__(self, input_dim, output_dim, device=torch.device('cpu'),
                 Lam_0_raw_init=0., optimize_prior=True,
                 hidden_dims=(50, 50), hidden_bias=True, activation='leaky_relu',
                 linear=True, bias=True):
        """
        Constructor for BayesianLastLayer.

        Parameters:
            input_dim (int): The number of input dimensions for the regression problem.
            output_dim (int): The number of output dimensions for the regression problem.

        Keywords:
            Lam_0_raw_init (float): The initial value for Lam_0_raw. Lam_0 = diag(exp(Lam_0_raw))
            optimize_prior (bool): Whether to optimize priors via backpropagation or not.
            hidden_dims (list[int] or tuple[int]): The number of hidden units for the neural networks layers.
            hidden_bias (bool): Whether to use bias terms for neural network layers or not.
            activation (str): The name of the activation function for neural network layers.
            linear (bool): Whether to use linear / identity features for the Bayesian weights.
            bias (bool): Whether to use bias / constant term for the Bayesian weights.
        """
        super().__init__(input_dim, output_dim, device=device)
        self.phi = DualModule(input_dim, hidden_dims, activation,
                              hidden_bias=hidden_bias, linear=linear, bias=bias).to(self.device)
        self.params = list(self.phi.parameters()) if hasattr(self.phi, "parameters") else []
        self.output_dim = output_dim
        self.m = self.phi.m
        # m neural features, k linear features, 1 bias term
        self.m_ = self.m + linear * self.k + bias
        # init params
        self.optimize_prior = optimize_prior
        self.Lam_0_raw = torch.full((self.m_,), Lam_0_raw_init, device=self.device, requires_grad=optimize_prior)
        self.params += [self.Lam_0_raw] if optimize_prior else []
        # posteriors
        self.Mu_n = None
        self.Lam_n = None
        self.Lam_n_inv = None
        # latent derivative priors
        self.M_prior = torch.zeros(self.d, self.k, device=self.device)
        self.U_prior = torch.eye(self.d, device=self.device)
        self.V_prior = torch.eye(self.k, device=self.device)

    @property
    def Lam_0(self):
        return self.Lam_0_raw.exp().diag()

    def _aleatoric_covariance(self):
        raise NotImplementedError

    def _bayesian_update_aleatoric(self):
        raise NotImplementedError

    def _bayesian_update(self, requires_grad=True):
        """
        Computes the Bayesian update using previously stored and whitened training data.

        Keywords:
            requires_grad (bool): Whether gradients are required or not.
        """
        # compute features
        Phi = self.phi.function(self.X_train_whitened, requires_grad=requires_grad)
        with torch.set_grad_enabled(requires_grad):
            Y = self.Y_train_whitened
            # compute posteriors
            self.Lam_n = Phi.t() @ Phi + self.Lam_0
            self.Lam_n_inv = torch.inverse(self.Lam_n)
            self.Mu_n = self.Lam_n_inv @ Phi.t() @ Y
            self._bayesian_update_aleatoric()

    def _init_posterior_batch(self, batch_idx, X_batch, y_batch):
        with torch.set_grad_enabled(False):
            Phi_b = self.phi.function(X_batch, requires_grad=False)
            phi_phi_b = Phi_b.t() @ Phi_b
            phi_y_b = Phi_b.t() @ y_batch
            self._batch_terms[batch_idx] = (phi_phi_b, phi_y_b)
            print(f"written {batch_idx}")

    def _bayesian_init_batch(self):
        self.Lam_n = self.Lam_0
        self.Mu_n = torch.zeros((self.m_, self.output_dim), device=self.device)

    def _bayesian_compute_batch(self, batch_idx, X_batch, y_batch, requires_grad=True):
        """
        Computes the Bayesian update using previously stored and whitened training data in a batch fashion.

        Keywords:
            requires_grad (bool): Whether gradients are required or not.
        """
        assert self.batch_mode
        # compute features
        Phi_b = self.phi.function(X_batch, requires_grad=requires_grad)
        with torch.set_grad_enabled(requires_grad):
            phi_phi_b = Phi_b.t() @ Phi_b
            phi_y_b = Phi_b.t() @ y_batch
            # finish computing posterior
            Lam_n_mu_n = self.Lam_n @ self.Mu_n
            self.Lam_n = self.Lam_n + phi_phi_b
            self.Lam_n_inv = torch.inverse(self.Lam_n)
            self.Mu_n = self.Lam_n_inv @ (Lam_n_mu_n + phi_y_b)

        self._bayesian_update_aleatoric()

    def _bayesian_update_batch(self, batch_idx, X_batch, y_batch, requires_grad=True):
        """
        Computes the Bayesian update using previously stored and whitened training data in a batch fashion.

        Keywords:
            requires_grad (bool): Whether gradients are required or not.
        """
        assert self.batch_mode
        assert self._batch_terms[batch_idx] is not None
        # approximate posterior from old batches
        # TODO: add prior last to simplify computation graph for EB?
        self.Lam_n = self.Lam_0
        self.Mu_n = torch.zeros((self.m_, y_batch.shape[1]), device=self.device)
        for b, v in enumerate(self._batch_terms):
            if b != batch_idx:
                _phi_phi_b, _phi_y_b = v
                Lam_n = self.Lam_n + _phi_phi_b
                Lam_n_inv = torch.inverse(Lam_n)
                self.Mu_n = Lam_n_inv @ (self.Lam_n @ self.Mu_n + _phi_y_b)
                self.Lam_n = Lam_n

        # compute features
        Phi_b = self.phi.function(X_batch, requires_grad=requires_grad)
        with torch.set_grad_enabled(requires_grad):
            phi_phi_b = Phi_b.t() @ Phi_b
            phi_y_b = Phi_b.t() @ y_batch
            # finish computing posterior
            Lam_n_mu_n = self.Lam_n @ self.Mu_n
            self.Lam_n = self.Lam_n + phi_phi_b
            self.Lam_n_inv = torch.inverse(self.Lam_n)
            self.Mu_n = self.Lam_n_inv @ (Lam_n_mu_n + phi_y_b)

        # update buffer
        self._batch_terms[batch_idx] = (phi_phi_b.detach(), phi_y_b.detach())

        self._bayesian_update_aleatoric()

    def _log_marginal_likelihood_aleatoric(self):
        raise NotImplementedError

    def _log_marginal_likelihood(self, requires_grad=True):
        """
        Computes the log-marginal likelihood using the previously computed Bayesian update.

        Keywords:
            requires_grad (bool): Whether gradients are required or not.

        Returns:
            log_marginal (torch.Tensor)[1]: The log-marginal likelihood of the training data.
        """
        # assemble noise matrix
        with torch.set_grad_enabled(requires_grad):
            # raw parameters are log proxies
            log_marginal = .5 * self.d * (self.Lam_0_raw.sum() - self.Lam_n.logdet())
            log_marginal += -.5 * self.n * self.d * math.log(2. * math.pi)
            log_marginal += self._log_marginal_likelihood_aleatoric()
            return log_marginal / self.n

    def _predictive_fkl(self, X, scaling_factor, prior, requires_grad=True):
        M, A, E = self._predict(X, requires_grad=requires_grad)
        V = A + E

        if prior == "white_noise":
            M_prior = torch.zeros_like(M, device=self.device)
            V_prior = torch.eye(self.d, device=self.device).repeat(V.shape[0], 1, 1)
        else:
            M_prior, A_prior, E_prior = prior._predict(X, requires_grad=False)
            V_prior = A_prior + E_prior
        V_prior_inv = V_prior.inverse()

        diff = (M_prior - M).unsqueeze(-1)

        KL = V_prior_inv.bmm(V).diagonal(dim1=-2, dim2=-1).sum(-1).mean()
        KL += diff.transpose(-2, -1).bmm(V_prior_inv).bmm(diff).mean()
        KL += -self.d
        KL += V_prior.logdet().mean() - V.logdet().mean()
        return scaling_factor * .5 * KL

    def _compute_jacobian_distribution(self, J_phi):
        n = J_phi.shape[0]
        M = self.Mu_n.repeat(n, 1, 1).transpose(1, 2).bmm(J_phi)
        U = self._aleatoric_covariance().repeat(n, 1, 1)
        V = J_phi.transpose(1, 2).bmm(self.Lam_n_inv.repeat(n, 1, 1)).bmm(J_phi)
        return M, U, V

    def _derivative_kld(self, scaling_factor, fixed_noise_prior, add_epsilon_noise, gamma, requires_grad=True):
        """
        Implements the sampling-based derivative fKL objective
        using the latest Bayesian update and an index set to approximate the stochastic Jacobian process.

        Parameters:
            scaling_factor (float): The scaling factor for the fKL objective.
            fixed_noise_prior (bool): Whether to use constant standard normal or model observation noise as fKL prior.
            add_epsilon_noise (bool): Whether to add small noise to training data to create index set for fKL objective.
            gamma (float): Variance of uncorrelated noise for index set.

        Keywords:
            requires_grad (bool): Whether gradients are required or not.

        Returns:
            {0} (torch.Tensor)[1]: The fKL objective
        """
        if add_epsilon_noise:
            index_set = self.X_train_whitened + dist.Normal(0, math.sqrt(gamma)).sample([self.n, self.k]).to(self.device)
        else:
            index_set = self.X_train_whitened
        J_phi = self.phi.jacobian(index_set, requires_grad=requires_grad)
        with torch.set_grad_enabled(requires_grad):
            M, U, V = self._compute_jacobian_distribution(J_phi)
            U_inv = U.inverse()
            V_inv = V.inverse()

            M_prior = self.M_prior.repeat(M.shape[0], 1, 1).to(self.device)
            U_prior = self.U_prior.repeat(U.shape[0], 1, 1).to(self.device) if fixed_noise_prior else U.detach()
            V_prior = self.V_prior.repeat(V.shape[0], 1, 1).to(self.device)

            M_ = M - M_prior
            trace_V = V_inv.bmm(V_prior).diagonal(dim1=-2, dim2=-1).sum(-1)
            trace_U = U_inv.bmm(U_prior).diagonal(dim1=-2, dim2=-1).sum(-1)
            kld = (trace_V * trace_U).mean()
            kld += (M_ * (U_inv.bmm(M_).bmm(V_inv.transpose(1, 2)))).sum((-1, -2)).mean()
            kld += -self.k * self.d
            kld += self.d * (V.logdet() - V_prior.logdet()).mean() + self.k * (U.logdet() - U_prior.logdet()).mean()
            kld *= .5
        return scaling_factor * kld / self.n

    def _eval_full(self, X, Y, whiten_input, batch_size=2000):
        """
        Evaluate RMSE + LLH + ENTR on full X,Y using batching to avoid OOM.
        Returns: (rmse, llh, entr) as floats (averaged over all points).
        """
        n = X.shape[0]
        rmse_sum, llh_sum, entr_sum = 0.0, 0.0, 0.0

        for p in range(0, n, batch_size):
            q = min(p + batch_size, n)
            bs = (q - p)
            rmse_b, llh_b, entr_b = self.evaluate(X[p:q, :], Y[p:q, :], whiten_input=whiten_input, requires_grad=False)
            rmse_sum += bs * rmse_b
            llh_sum += bs * llh_b
            entr_sum += bs * entr_b

        denom = float(n)
        return rmse_sum / denom, llh_sum / denom, entr_sum / denom

    #
    # def fit(self, X_train, Y_train, X_val=None, Y_val=None, X_test=None, Y_test=None,
    #         whiten_input=True, z_score_output=False, learning_rate=0.0001, num_epochs=10000,
    #         latent_derivatives=False, scaling_factor=1., fixed_noise_prior=False, add_epsilon_noise=True, gamma=.01,
    #         predictive_fkl_prior=None, num_samples=100, ignore_marginal_likelihood=False,
    #         disable_tqdm=False):

    def fit(self, X_train, Y_train, X_val=None, Y_val=None, X_test=None, Y_test=None,
            whiten_input=True, z_score_output=False, learning_rate=0.0001, num_epochs=10000,
            latent_derivatives=False, scaling_factor=1., fixed_noise_prior=False, add_epsilon_noise=True, gamma=.01,
            predictive_fkl_prior=None, num_samples=100, ignore_marginal_likelihood=False,
            disable_tqdm=False,
            epoch_csv_path=None,
            eval_batch_size=2000,
            log_every=1):


        """
        Implements full training procedure, including whitening, validation and optional fKL objective.

        Parameters:
            X_train (torch.Tensor)[n, k]: The input training data.
            Y_train (torch.Tensor)[n, d]: The output training data.

        Keywords:
            X_val (torch.Tensor)[n_val, k]: Optional input validation data.
            Y_val (torch.Tensor)[n_val, d]: Optional output validation data.
            X_test (torch.Tensor)[n_test, k]: Optional input test data (for visualization only).
            Y_test (torch.Tensor)[n_test, d]: Optional output test data (for visualization only).
            learning_rate (float): The learning rate for the gradient descent (Adam) optimizer.
            num_epochs (int): The number of training epochs.
            latent_derivatives (bool): Whether to use the fKL objective or not.
            scaling_factor (float): The scaling factor for the fKL objective.
            fixed_noise_prior (bool): Whether to use constant standard normal or model observation noise as fKL prior.
            add_epsilon_noise (bool): Whether to add small noise to training data to create index set for fKL objective.
            gamma (float): Variance of uncorrelated noise for index set.
            disable_tqdm (bool): Whether to disable tqdm progress bars or not.
        """
        self._prepare_data(X_train, Y_train, X_val, Y_val, X_test, Y_test,
                           whiten_input=whiten_input, z_score_output=z_score_output)
        # initialize optimizer
        params = [{'params': self.params}]
        optimizer = torch.optim.Adam(params, lr=learning_rate)
        # initialize traces

        self._reset_traces()
        self.traces.setdefault("train_rmse", [])
        self.traces.setdefault("train_nll", [])
        self.traces.setdefault("test_rmse", [])
        self.traces.setdefault("test_nll", [])

        # --- NEW: per-epoch CSV logging setup ---
        csv_f = None
        csv_writer = None
        if epoch_csv_path is not None:
            os.makedirs(os.path.dirname(epoch_csv_path), exist_ok=True)
            is_new = not os.path.exists(epoch_csv_path)
            csv_f = open(epoch_csv_path, "a", newline="")
            csv_writer = csv.writer(csv_f)
            if is_new:
                csv_writer.writerow(["epoch", "train_rmse", "train_nll", "test_rmse", "test_nll"])

        # ---------------------------------------

        low = torch.min(self.X_train_whitened, dim=0)[0]
        high = torch.max(self.X_train_whitened, dim=0)[0]
        d = high - low
        eps = 1e-6
        d_safe = torch.clamp(d, min=eps)
        a = low - 0.5 * d_safe
        b = high + 0.5 * d_safe
        b = torch.maximum(b, a + eps)
        unif = dist.Uniform(a, b)
        # unif = dist.Uniform(a, b)

        # train for 'num_epochs' epochs
        iterator = range(num_epochs) if disable_tqdm else tqdm.tqdm(range(num_epochs), desc="Epoch")
        for _ in iterator:
            optimizer.zero_grad()
            self._bayesian_update()
            log_marginal = self._log_marginal_likelihood()
            # maximize log marginal likelihood
            objective = -log_marginal
            self.traces['objective'].append(objective.item())
            # minimize KL
            if latent_derivatives:
                kl_divergence = self._derivative_kld(scaling_factor=scaling_factor,
                                                     fixed_noise_prior=fixed_noise_prior,
                                                     add_epsilon_noise=add_epsilon_noise, gamma=gamma)
                objective = objective + kl_divergence
                self.traces['kld'].append(kl_divergence.item())
            elif predictive_fkl_prior is not None:
                X = torch.cat([self.X_train_whitened, unif.sample([num_samples])], dim=0)
                predictive_fkl = self._predictive_fkl(X, scaling_factor=scaling_factor,
                                                      prior=predictive_fkl_prior)
                if ignore_marginal_likelihood:
                    objective = predictive_fkl
                else:
                    objective = objective + predictive_fkl
                self.traces['kld'].append(predictive_fkl.item())
            objective.backward()
            optimizer.step()
            self._running_eval()
            # Local progress reporting only; the original training math is unchanged.
            completed = len(self.traces["objective"])
            if completed == 1 or completed % 1000 == 0:
                print(f"LDBLL: epoch {completed}/{num_epochs}", flush=True)

            # --- NEW: log per-epoch train/test RMSE + NLL ---
            # Note: evaluate() expects Y_ in the ORIGINAL scale if whiten_input=True.
            # Your TrainingScript passes y_all_train and y_test in original scale, so this is correct.
            if (len(self.traces["objective"]) % log_every) == 0:
                tr_rmse, tr_llh, _ = self._eval_full(
                    X_train, Y_train, whiten_input=whiten_input, batch_size=eval_batch_size
                )
                tr_nll = -float(tr_llh)

                if X_test is not None and Y_test is not None:
                    te_rmse, te_llh, _ = self._eval_full(
                        X_test, Y_test, whiten_input=whiten_input, batch_size=eval_batch_size
                    )
                    te_nll = -float(te_llh)
                else:
                    te_rmse, te_nll = float("nan"), float("nan")

                self.traces["train_rmse"].append(float(tr_rmse))
                self.traces["train_nll"].append(float(tr_nll))
                self.traces["test_rmse"].append(float(te_rmse))
                self.traces["test_nll"].append(float(te_nll))

                if csv_writer is not None:
                    epoch_idx = len(self.traces["objective"])
                    csv_writer.writerow([epoch_idx, tr_rmse, tr_nll, te_rmse, te_nll])
                    csv_f.flush()
            # -----------------------------------------------
        if csv_f is not None:
            csv_f.close()

    def fit_batch(self, n_batches,
            X_train, Y_train, X_val=None, Y_val=None, X_test=None, Y_test=None,
            whiten_input=True, z_score_output=True, learning_rate=0.0001, num_epochs=10000,
            latent_derivatives=True, scaling_factor=1., fixed_noise_prior=False, add_epsilon_noise=True, gamma=.01,
            predictive_fkl_prior=None, num_samples=100, ignore_marginal_likelihood=False,
            disable_tqdm=False,
            epoch_csv_path=None,
            eval_batch_size=2000,
            log_every=1):
        """
        Implements full training procedure, including whitening, validation and optional fKL objective.

        Parameters:
            X_train (torch.Tensor)[n, k]: The input training data.
            Y_train (torch.Tensor)[n, d]: The output training data.
            n_batch (int): number of batches

        Keywords:
            X_val (torch.Tensor)[n_val, k]: Optional input validation data.
            Y_val (torch.Tensor)[n_val, d]: Optional output validation data.
            X_test (torch.Tensor)[n_test, k]: Optional input test data (for visualization only).
            Y_test (torch.Tensor)[n_test, d]: Optional output test data (for visualization only).
            learning_rate (float): The learning rate for the gradient descent (Adam) optimizer.
            num_epochs (int): The number of training epochs.
            latent_derivatives (bool): Whether to use the fKL objective or not.
            scaling_factor (float): The scaling factor for the fKL objective.
            fixed_noise_prior (bool): Whether to use constant standard normal or model observation noise as fKL prior.
            add_epsilon_noise (bool): Whether to add small noise to training data to create index set for fKL objective.
            gamma (float): Variance of uncorrelated noise for index set.
            disable_tqdm (bool): Whether to disable tqdm progress bars or not.
        """
        self._prepare_data(X_train, Y_train, X_val, Y_val, X_test, Y_test,
                           whiten_input=whiten_input, z_score_output=z_score_output)
        # initialize optimizer
        params = [{'params': self.params}]
        optimizer = torch.optim.Adam(params, lr=learning_rate)
        # initialize traces
        self._reset_traces()
        self.traces.setdefault("train_rmse", [])
        self.traces.setdefault("train_nll", [])
        self.traces.setdefault("test_rmse", [])
        self.traces.setdefault("test_nll", [])

        csv_f = None
        csv_writer = None
        if epoch_csv_path is not None:
            os.makedirs(os.path.dirname(epoch_csv_path), exist_ok=True)
            is_new = not os.path.exists(epoch_csv_path)
            csv_f = open(epoch_csv_path, "a", newline="")
            csv_writer = csv.writer(csv_f)
            if is_new:
                csv_writer.writerow(["epoch", "train_rmse", "train_nll", "test_rmse", "test_nll"])


        low = torch.min(self.X_train_whitened, dim=0)[0]
        high = torch.max(self.X_train_whitened, dim=0)[0]
        d = high - low
        eps = 1e-6
        d_safe = torch.clamp(d, min=eps)
        a = low - 0.5 * d_safe
        b = high + 0.5 * d_safe
        b = torch.maximum(b, a + eps)
        unif = dist.Uniform(a, b)

        # train for 'num_epochs' epochs
        iterator = range(num_epochs + 1) if disable_tqdm else tqdm.tqdm(range(num_epochs + 1), desc="Epoch")
        batch_size = self.n // n_batches
        assert n_batches * batch_size <= self.n
        self.batch_mode = True
        permutations = torch.randperm(self.n)
        for i in iterator:
            optimizer.zero_grad()
            self._bayesian_init_batch()
            for b in np.random.permutation(n_batches):
                idxs = permutations[b * batch_size:(b+1) * batch_size]
                X_batch, Y_batch = self.X_train_whitened[idxs, :], self.Y_train_whitened[idxs, :]
                self._bayesian_compute_batch(b, X_batch, Y_batch)
            log_marginal = self._log_marginal_likelihood()
            # maximize log marginal likelihood
            objective = -log_marginal
            self.traces['objective'].append(objective.item())
            # minimize KL
            if latent_derivatives:
                kl_divergence = self._derivative_kld(scaling_factor=scaling_factor,
                                                     fixed_noise_prior=fixed_noise_prior,
                                                     add_epsilon_noise=add_epsilon_noise, gamma=gamma)
                objective = objective + kl_divergence
                self.traces['kld'].append(kl_divergence.item())
            elif predictive_fkl_prior is not None:
                X = torch.cat([X_batch, unif.sample([num_samples // n_batches])], dim=0)
                predictive_fkl = self._predictive_fkl(X, scaling_factor=scaling_factor,
                                                      prior=predictive_fkl_prior)
                if ignore_marginal_likelihood:
                    objective = predictive_fkl
                else:
                    objective = objective + predictive_fkl
                self.traces['kld'].append(predictive_fkl.item())
            objective.backward()
            optimizer.step()
            if i > 0:
                self._running_eval()
                if (len(self.traces["objective"]) % log_every) == 0:
                    tr_rmse, tr_llh, _ = self._eval_full(
                        X_train, Y_train, whiten_input=whiten_input, batch_size=eval_batch_size
                    )
                    tr_nll = -float(tr_llh)

                    if X_test is not None and Y_test is not None:
                        te_rmse, te_llh, _ = self._eval_full(
                            X_test, Y_test, whiten_input=whiten_input, batch_size=eval_batch_size
                        )
                        te_nll = -float(te_llh)
                    else:
                        te_rmse, te_nll = float("nan"), float("nan")

                    self.traces["train_rmse"].append(float(tr_rmse))
                    self.traces["train_nll"].append(float(tr_nll))
                    self.traces["test_rmse"].append(float(te_rmse))
                    self.traces["test_nll"].append(float(te_nll))

                    if csv_writer is not None:
                        epoch_idx = len(self.traces["objective"])
                        csv_writer.writerow([epoch_idx, tr_rmse, tr_nll, te_rmse, te_nll])
                        csv_f.flush()
        self.batch_mode = False
        if csv_f is not None:
            csv_f.close()

    def _rmse(self, mean, Y_):
        return ((mean - Y_) ** 2).sum(dim=1).mean().sqrt()

    def _llh(self, mean, variance, Y_):
        raise NotImplementedError

    def _entr(self, variance):
        raise NotImplementedError

    def evaluate(self, X_, Y_, whiten_input=True, requires_grad=False):
        """
        Computes RMSE, log-likelihood and predictive entropy for a batch of data.

        Parameters:
            X_ (torch.Tensor)[*, k]: The input data.
            Y_ (torch.Tensor)[*, d]: The ground truth output data.

        Keywords:
            whiten_input (bool): Whether the new input data should be whitened.
            requires_grad (bool): Whether gradients are required or not.

        Returns:
            RMSE (float): The root mean squared error between prediction and ground truth.
            LLH (float): The average log-likelihood of the ground truth output w.r.t. the prediction.
            ENTR (float): The average entropy of the predictive distribution.
        """
        mean, variance = self.predict_mean_variance(X_, whiten_input=whiten_input, requires_grad=requires_grad)
        with torch.set_grad_enabled(requires_grad):
            # compute evaluation metrics
            rmse = self._rmse(mean, Y_)
            llh = self._llh(mean, variance, Y_)
            entr = self._entr(variance)
            return rmse.item(), llh.item(), entr.item()

    def _add_aleatoric_params(self, state_dict):
        raise NotImplementedError

    def save(self, filepath):
        """
        Saves the current model to the disk, only keeping prediction variables, no optimization information.

        Parameters:
            filepath (str): The destination to save the model.
        """
        state_dict = dict()
        state_dict['phi'] = self.phi.state_dict()
        state_dict['Lam_0_raw'] = self.Lam_0_raw
        state_dict['optimize_prior'] = self.optimize_prior
        state_dict['Mu_n'] = self.Mu_n
        state_dict['Lam_n_inv'] = self.Lam_n_inv
        self._add_aleatoric_params(state_dict)
        self._add_whitening_params(state_dict)
        torch.save(state_dict, filepath)

    def _pop_aleatoric_params(self, state_dict):
        raise NotImplementedError

    def load(self, filepath):
        """
        Loads a previously saved model from the disk.

        Parameters:
            filepath (str): The destination of the saved model.
        """
        state_dict = torch.load(filepath)
        self.Lam_0_raw = state_dict.pop('Lam_0_raw')
        if state_dict['optimize_prior'] != self.optimize_prior:
            print("Warning: Mismatch when loading parameter 'optimize_prior'.")
        self.optimize_prior = state_dict.pop('optimize_prior')
        self.Mu_n = state_dict.pop('Mu_n')
        self.Lam_n_inv = state_dict.pop('Lam_n_inv')
        self._pop_aleatoric_params(state_dict)
        self._pop_whitening_params(state_dict)
        self.phi.load_state_dict(state_dict['phi'])


class GaussianBayesianLastLayer(BayesianLastLayer):
    """
    Based on BayesianLastLayer, this class implements a Gaussian Bayesian last layer network.

    Attributes:
        Sigma_raw (torch.Tensor)[d]: Proxy for learning observation noise to assert positive constraint.
    """

    def __init__(self, input_dim, output_dim, device=torch.device('cpu'),
                 Sigma_raw_init=0., Lam_0_raw_init=0., optimize_prior=True,
                 hidden_dims=(50, 50), hidden_bias=True, activation='leaky_relu',
                 linear=True, bias=True):
        """
        Constructor for GaussianBayesianLastLayer.

        Parameters:
            input_dim (int): The number of input dimensions for the regression problem.

        Keywords:
            Sigma_raw_init (float): The initial value for Sigma_raw. Sigma = diag(exp(Sigma_raw))
            Lam_0_raw_init (float): The initial value for Lam_0_raw. Lam_0 = diag(exp(Lam_0_raw))
            optimize_prior (bool): Whether to optimize priors via backpropagation or not.
            hidden_dims (list[int] or tuple[int]): The number of hidden units for the neural networks layers.
            hidden_bias (bool): Whether to use bias terms for neural network layers or not.
            activation (str): The name of the activation function for neural network layers.
            linear (bool): Whether to use linear / identity features for the Bayesian weights.
            bias (bool): Whether to use bias / constant term for the Bayesian weights.
        """
        super().__init__(input_dim, output_dim, device=device,
                         Lam_0_raw_init=Lam_0_raw_init, optimize_prior=optimize_prior,
                         hidden_dims=hidden_dims, hidden_bias=hidden_bias, activation=activation,
                         linear=linear, bias=bias)
        self.Sigma_raw = torch.full((self.d,), Sigma_raw_init, device=self.device, requires_grad=optimize_prior)
        self.params += [self.Sigma_raw] if optimize_prior else []

    @property
    def Sigma(self):
        return self.Sigma_raw.exp().diag()

    def _aleatoric_covariance(self):
        return self.Sigma

    def _bayesian_update_aleatoric(self):
        pass

    def _log_marginal_likelihood_aleatoric(self):
        Y = self.Y_train_whitened
        log_marginal = -.5 * self.n * self.Sigma_raw.sum()
        log_marginal += -.5 * (self.Sigma.inverse() @ (Y.t() @ Y - self.Mu_n.t() @ self.Lam_n @ self.Mu_n)).trace()
        return log_marginal

    def _predict(self, X_, requires_grad=False):
        Phi_ = self.phi.function(X_, requires_grad=requires_grad)
        with torch.set_grad_enabled(requires_grad):
            t = Phi_.shape[0]
            mean = Phi_ @ self.Mu_n
            aleatoric = self.Sigma.diag().repeat(t, 1)
            epistemic = aleatoric * (Phi_ @ self.Lam_n_inv @ Phi_.t()).diag().view(t, 1)
        return mean, aleatoric.diag_embed(), epistemic.diag_embed()

    def _llh(self, mean, variance, Y_):
        return mvn_logprob(mean, variance, Y_).mean()

    def _entr(self, variance):
        return mvn_entropy(variance).mean()

    def _add_aleatoric_params(self, state_dict):
        state_dict['Sigma_raw'] = self.Sigma_raw

    def _pop_aleatoric_params(self, state_dict):
        self.Sigma_raw = state_dict.pop('Sigma_raw')
        self.params += [self.Sigma_raw] if self.optimize_prior else []



# --- Experiment I/O: these helpers are intentionally local to every script. ---
def experiment_setup():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--data", default=CONFIG["data_path"])
    parser.add_argument("--output", default=CONFIG["output_root"], help="Exact run directory; defaults create a unique subdirectory")
    parser.add_argument("--device", default=CONFIG["device"])
    parser.add_argument("--epochs", type=int, help="Optional training-budget override for smoke tests")
    parser.add_argument("--learning-rate", type=float, help="Override the model learning rate")
    parser.add_argument("--repulsion-strength", type=float, help="Override repulsion coefficient for repulsive methods")
    parser.add_argument("--reuse-stage1", help="BDKN stage1.pt to reuse; deep ensemble only")
    args = parser.parse_args()
    cfg = dict(CONFIG)
    if args.learning_rate is not None:
        if not np.isfinite(args.learning_rate) or args.learning_rate <= 0: parser.error("Learning rate must be finite and positive")
        cfg["lr"] = args.learning_rate
    if args.repulsion_strength is not None:
        if "repulsion_strength" not in cfg: parser.error("This method does not use repulsion")
        if not np.isfinite(args.repulsion_strength) or args.repulsion_strength < 0: parser.error("Repulsion strength must be finite and nonnegative")
        cfg["repulsion_strength"] = args.repulsion_strength
    if args.epochs is not None:
        if args.epochs < 1: parser.error("--epochs must be positive")
        cfg["epochs"] = args.epochs
    cfg["device"] = ("cuda:0" if torch.cuda.is_available() else "cpu") if args.device == "auto" else args.device
    torch.set_num_threads(cfg["cpu_threads"])
    random.seed(cfg["seed"]); np.random.seed(cfg["seed"]); torch.manual_seed(cfg["seed"])
    if torch.cuda.is_available(): torch.cuda.manual_seed_all(cfg["seed"])
    data_path = Path(args.data)
    if not data_path.is_absolute(): data_path = ROOT / data_path
    if not data_path.is_file():
        raise FileNotFoundError(f"Missing {data_path}. Run: python generate_data.py")
    with np.load(data_path, allow_pickle=False) as archive:
        data = {k: archive[k] for k in archive.files}
    for name in ("x_train", "y_train", "x_test", "y_test", "x_grid", "f_grid"):
        if name not in data or data[name].ndim != 2 or data[name].shape[1] != 1 or not np.isfinite(data[name]).all():
            raise ValueError(f"Invalid dataset array: {name}")
    for x, y in (("x_train", "y_train"), ("x_test", "y_test"), ("x_grid", "f_grid")):
        if len(data[x]) != len(data[y]) or len(data[x]) < 2: raise ValueError(f"Invalid lengths: {x}, {y}")
    cfg["data_path"] = str(data_path.resolve())
    cfg["dataset_sha256"] = hashlib.sha256(data_path.read_bytes()).hexdigest()
    cfg["reuse_stage1"] = args.reuse_stage1
    output = Path(args.output)
    if not output.is_absolute(): output = ROOT / output
    if args.output == CONFIG["output_root"]:
        output = output / (METHOD + "_" + datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S_%f"))
    output.mkdir(parents=True, exist_ok=False)
    (output / "config.json").write_text(json.dumps(cfg, indent=2) + "\n")
    return cfg, data, output, torch.device(cfg["device"])


def array(value):
    if isinstance(value, torch.Tensor): value = value.detach().cpu().numpy()
    return np.asarray(value, dtype=np.float64).reshape(-1)


def gaussian_prediction(mean, variance):
    mean, variance = array(mean), array(variance)
    if not np.isfinite(variance).all() or np.any(variance <= 0):
        raise FloatingPointError("Nonpositive or nonfinite predictive variance")
    scale = np.sqrt(variance)
    return dict(mean=mean, scale=scale, lower=mean-1.959963984540054*scale,
                upper=mean+1.959963984540054*scale, family="gaussian", df=None)



def training_clock(device):
    """Wall time with CUDA synchronization, so queued GPU work is counted."""
    if torch.device(device).type == "cuda": torch.cuda.synchronize(device)
    return time.perf_counter()


def record_result(label, test, grid, data, output, cfg, seconds):
    """Score noisy held-out observations and save predictions in original units."""
    from scipy.stats import norm, t
    for prediction, n in ((test, len(data["x_test"])), (grid, len(data["x_grid"]))):
        for key in ("mean", "scale", "lower", "upper"):
            values = array(prediction[key]); prediction[key] = values
            if len(values) != n or not np.isfinite(values).all(): raise FloatingPointError(f"Invalid {label} {key}")
        if np.any(prediction["scale"] <= 0) or np.any(prediction["lower"] > prediction["upper"]):
            raise FloatingPointError(f"Invalid {label} interval/scale")
    target = data["y_test"].reshape(-1)
    distribution = norm if test["family"] == "gaussian" else t
    kwargs = {} if test["family"] == "gaussian" else {"df": test["df"]}
    nll = -distribution.logpdf(target, loc=test["mean"], scale=test["scale"], **kwargs).mean()
    metrics = dict(method=label, rmse=float(np.sqrt(np.mean((target-test["mean"])**2))), nll=float(nll),
                   predictive_family=test["family"], seconds=seconds, dataset_sha256=cfg["dataset_sha256"])
    metrics.update(training_seconds=cfg.get("_training_seconds"),
                   stage1_training_seconds=cfg.get("_stage1_training_seconds"),
                   stage2_training_seconds=cfg.get("_stage2_training_seconds"),
                   training_reused=cfg.get("_training_reused", False))
    if not np.isfinite([metrics["rmse"], metrics["nll"]]).all(): raise FloatingPointError(f"Nonfinite metrics: {label}")
    folder=output / label; folder.mkdir()
    (folder / "metrics.json").write_text(json.dumps(metrics, indent=2) + "\n")
    arrays={}
    for split,pred in (("test",test),("grid",grid)):
        for key in ("mean","scale","lower","upper"): arrays[split+"_"+key]=pred[key]
    arrays.update(x_test=data["x_test"], y_test=data["y_test"], x_grid=data["x_grid"],
                  f_grid=data["f_grid"], df=np.nan if test["df"] is None else test["df"])
    np.savez_compressed(folder / "predictions.npz", **arrays)
    fig,ax=plt.subplots(figsize=(8,4))
    draw_prediction(ax,label,grid,data,metrics)
    fig.tight_layout(); fig.savefig(folder / "prediction.png", dpi=180); plt.close(fig)
    print(f"{label}: RMSE={metrics['rmse']:.5f}, NLL={metrics['nll']:.5f}", flush=True)
    return metrics


def draw_prediction(ax, label, grid, data, metrics):
    x=data["x_grid"].reshape(-1)
    ax.fill_between(x,grid["lower"],grid["upper"],alpha=.22,label="95% predictive interval")
    ax.plot(x,grid["mean"],label="Prediction")
    ax.plot(x,data["f_grid"].reshape(-1),"k--",lw=1,label="True function")
    ax.scatter(data["x_train"],data["y_train"],s=9,c="black",alpha=.45,label="Training data")
    ax.set(xlabel="x",ylabel="y",title=f"{label} | RMSE {metrics['rmse']:.4f} | NLL {metrics['nll']:.4f}",xlim=(-1,1))
    ax.legend(fontsize=7)


def save_history(output, rows):
    if not rows: return
    with (output / "history.csv").open("w",newline="") as handle:
        writer=csv.DictWriter(handle,fieldnames=list(rows[0])); writer.writeheader(); writer.writerows(rows)


def finish(output, rows):
    (output / "metrics.json").write_text(json.dumps(rows,indent=2)+"\n")
    print(f"Saved {output}", flush=True)



# --- Training and comparison entrypoint ---

def main():
    cfg,data,output,device=experiment_setup()
    if cfg["reuse_stage1"]: raise ValueError("--reuse-stage1 is only for deep_ensemble")
    set_input_normalization_mode(cfg["input_norm_type"])
    tensors={k:torch.tensor(data[k],dtype=torch.float32,device=device) for k in ("x_train","y_train","x_test","x_grid")}
    start=time.perf_counter()
    if METHOD == "ldbll":
        model=GaussianBayesianLastLayer(1,1,device=device,optimize_prior=cfg["optimize_prior"],
            hidden_dims=tuple(cfg["hidden_dims"]),hidden_bias=cfg["hidden_bias"],activation=cfg["activation"],
            linear=cfg["linear"],bias=cfg["bias"])
        fit_t0=training_clock(device)
        model.fit(tensors["x_train"],tensors["y_train"],learning_rate=cfg["lr"],num_epochs=cfg["epochs"],
            whiten_input=cfg["normalize_input"],z_score_output=cfg["normalize_output"],
            latent_derivatives=cfg["latent_derivatives"],scaling_factor=cfg["scaling_factor"],
            fixed_noise_prior=cfg["fixed_noise_prior"],add_epsilon_noise=cfg["add_epsilon_noise"],gamma=cfg["gamma"],
            disable_tqdm=True,log_every=cfg["epochs"]+1)
        # Original fit retains the posterior from its last pre-update pass.
        # Preserve that convention rather than silently changing the algorithm.
    else:
        model=GaussianProcess(1,1,kernel=tuple(cfg["kernel"]),n_inducing=cfg["n_inducing"],device=device)
        fit_t0=training_clock(device)
        model.fit(tensors["x_train"],tensors["y_train"],learning_rate=cfg["lr"],num_epochs=cfg["epochs"],
            whiten_input=cfg["normalize_input"],z_score_output=cfg["normalize_output"],
            enable_early_stopping=False,disable_tqdm=True,log_every=cfg["epochs"]+1)
    cfg["_training_seconds"]=training_clock(device)-fit_t0
    print(f"{METHOD}: finished {len(model.traces['objective'])} epochs",flush=True)
    def prediction(key):
        mean,var=model.predict(tensors[key],whiten_input=cfg["normalize_input"],requires_grad=False)
        return gaussian_prediction(mean,var.reshape(-1))
    rows=[record_result(METHOD,prediction("x_test"),prediction("x_grid"),data,output,cfg,time.perf_counter()-start)]
    save_history(output,[dict(epoch=i+1,objective=v,derivative_kl=model.traces['kld'][i] if model.traces['kld'] else 0.)
                         for i,v in enumerate(model.traces['objective'])])
    model.save(str(output / "model.pt")); finish(output,rows)


if __name__ == "__main__":
    main()
